// HasInsight applies the HasEdge predicate on the "insight" edge.
func HasInsight() predicate.WorkInsightReview {
	return predicate.WorkInsightReview(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, InsightTable, InsightColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasInsightWith applies the HasEdge predicate on the "insight" edge with a given conditions (other predicates).
func HasInsightWith(preds ...predicate.WorkInsight) predicate.WorkInsightReview {
	return predicate.WorkInsightReview(func(s *sql.Selector) {
		step := newInsightStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.WorkInsightReview) predicate.WorkInsightReview {
	return predicate.WorkInsightReview(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.WorkInsightReview) predicate.WorkInsightReview {
	return predicate.WorkInsightReview(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.WorkInsightReview) predicate.WorkInsightReview {
	return predicate.WorkInsightReview(sql.NotPredicates(p))
}
